param([string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$BuildRoot='')
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot out/staging};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot)
$root=Join-Path $ProjectRoot ('artifacts/audio-delivery-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null;$service=$null;$provider=$null;$checks=0
$env:HIBERNATION_SESSION_KEY='audio-delivery-fixture';$env:TEMP="$BuildRoot/tmp";$env:TMP=$env:TEMP
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name,[int]$Seconds=15){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 50};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer audio-delivery-fixture'};TimeoutSec=10};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 40 -Compress))};Invoke-RestMethod @a}
function Plugin($Name,$Arguments=@{}){$id=[Guid]::NewGuid().ToString('N');$null=Api '/api/plugin/test' @{tool=$Name;args=$Arguments;request_id=$id};Wait-For {$script:result=Api '/api/plugin/result';$script:result.request_id-eq$id-and$script:result.state-in@('succeeded','failed','paused')} $Name;return $script:result.result}
function Speech{(Api '/api/capabilities').plugins.Where({$_.id-eq'tts'})[0].current}
try{
 $provider=Start-Process "$BuildRoot/Hibernation_TestProvider.exe" -ArgumentList ('"'+$root+'/provider"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/provider.log" -RedirectStandardError "$root/provider-error.log";Wait-For {Test-Path "$root/provider/port"} 'provider';$fixture='http://127.0.0.1:'+(Get-Content "$root/provider/port")
 $cfg=Get-Content "$ProjectRoot/config/example.json" -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot="$root/data";$cfg.characterRoot="$ProjectRoot/character";$cfg.uiRoot="$ProjectRoot/ui";$cfg.pluginRoot="$BuildRoot/plugins";$cfg.solitudeIntervalMs=604800000;$cfg.maxStartsPerHour=1000;$cfg.profiles=@($cfg.profiles[0]);$cfg.plugins=@{tts=@{enabled=$true;backend='http';origin=$fixture;path='/v1/audio/speech';volume=0;maxSeconds=3;autoSpeak=$false}};$cfg|ConvertTo-Json -Depth 40|Set-Content "$root/config.json" -Encoding utf8
 $service=Start-Process "$BuildRoot/hibernation-agent.exe" -ArgumentList ('--config "'+$root+'/config.json" --ready-file "'+$root+'/ready.json"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/service.log" -RedirectStandardError "$root/error.log";Wait-For {if($service.HasExited){throw 'fixture exited'};Test-Path "$root/ready.json"} 'backend';$script:origin='http://127.0.0.1:'+((Get-Content "$root/ready.json" -Raw|ConvertFrom-Json).port)
 Wait-For {$script:observed=(Plugin 'speech.output_status').result;$observed.engine.ready-and$observed.checked_at_ms-gt0-and$observed.own_sessions.Count-gt0} 'real current-process output session'
 Check ($observed.engine.real_device-and$observed.engine.name-eq'Miniaudio'-and$observed.engine.channels-eq2) 'speech uses an actual stereo engine backend';Check ($observed.console.available-or$observed.multimedia.available) 'default output availability comes from the OS';Check ($observed.own_sessions.Count-le32-and$observed.own_sessions[0].endpoint_name.Length-gt0) 'bounded current-process sessions include actual endpoint names';Check ($observed.assessment.code-eq'app_volume_zero'-and!$observed.assessment.heard_confirmed) 'configured zero voice volume is explicit without claiming user audibility';Check ($observed.note.Contains('没有录音')-and$observed.note.Contains('忽视')) 'observation cannot become evidence of user neglect'
 $watch=[Diagnostics.Stopwatch]::StartNew();$status=Plugin 'speech.output_status';Check ($status.ok-and$watch.ElapsedMilliseconds-lt1000) 'reading cached diagnostics does not wait for an OS refresh';Check ((Invoke-RestMethod ($fixture+'/fixture/health')).audio_calls-eq0) 'checking output does not synthesize or play a test voice'
 $null=Plugin 'speech.speak' @{text='这段验证的音量为零。';max_seconds=1};Wait-For {!(Speech).active} 'silent voice finishes';$spoken=(Plugin 'speech.status').result;Check ($spoken.started_count-eq1-and$spoken.completed_count-eq1-and$spoken.output.engine.ready) 'actual speech and diagnostic workers coexist';$baseline=(Get-Process -Id $service.Id).HandleCount
 for($i=0;$i-lt3;$i++){$settings=(Api '/api/dashboard').settings;$settings.plugins.tts.enabled=$false;$null=Api '/api/settings' @{settings=$settings};$settings.plugins.tts.enabled=$true;$null=Api '/api/settings' @{settings=$settings};Wait-For {(Plugin 'speech.output_status').result.engine.ready} 'audio plugin reload'};Check ((Get-Process -Id $service.Id).HandleCount-lt$baseline+30) 'audio monitoring and device handles release on plugin reload'
 $settings=(Api '/api/dashboard').settings;$settings.plugins.tts.path='/fixture/slow-audio';$null=Api '/api/settings' @{settings=$settings};$calls=(Invoke-RestMethod ($fixture+'/fixture/health')).audio_calls;$null=Api '/api/plugin/test' @{tool='speech.speak';args=@{text='这份暂停的试读不应重放。'};request_id='paused-audio'};Wait-For {(Invoke-RestMethod ($fixture+'/fixture/health')).audio_calls-gt$calls} 'actual pending voice synthesis';$null=Api '/api/control' @{paused=$true};Wait-For {(Api '/api/plugin/result').state-eq'paused'} 'operator request paused';$paused=Api '/api/plugin/result';Check ($paused.request_id-eq'paused-audio'-and$paused.result.error.code-eq'operator_paused') 'paused operator result is a valid bounded receipt';$null=Api '/api/control' @{paused=$false};Start-Sleep -Milliseconds 3400;Check (!(Speech).active-and(Speech).started_count-eq0) 'resuming does not replay a paused operator voice'
 $settings.plugins.tts.path='/v1/audio/speech';$null=Api '/api/settings' @{settings=$settings};$fresh=Plugin 'speech.speak' @{text='新的试读可以正常开始。';max_seconds=1};Check $fresh.ok 'a fresh request replaces the paused operator slot';Wait-For {!(Speech).active} 'fresh voice finishes';$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'speech and diagnostic threads stop cleanly'
 @{completed=$true;checks=$checks;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content "$root/acceptance.json";Write-Output "Audio delivery passed: $checks checks. Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
